flow.typescript:
// D36 · Part 0~4 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d36_flow.ts   (소리·데이터는 코드 안에서 합성해요)
//   합성 말소리에서 말투 숫자 → 기준선 → 감정 → 타임라인 → 소리 이벤트 → 에스컬레이션까지 한 번에


const SR = 16000; // 말소리 분석용 표본화율 (16 kHz)
const HOP = 320; // 20 ms마다 한 번 잼

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}

function speak(f0: number = 140, rate: number = 4, amp: number = 0.3, nSyl: number = 10, seed: number = 0): Float32Array {
  // [대체] TTS 대신 배음 3개짜리 합성 말소리: 음절마다 앞 70%는 소리, 뒤 30%는 쉼
  const rnd = mulberry32(seed);
  const L = Math.floor(SR / rate);
  const v = Math.floor(L * 0.7);
  const y = new Float32Array(nSyl * L);
  for (let k = 0; k < nSyl; k++) {
    const f = f0 * (1 + 0.03 * Math.sin(1.7 * k)); // 억양이 조금 흔들림
    const seg = new Float64Array(v);
    let peak = 0;
    for (let i = 0; i < v; i++) {
      let s = 0;
      for (let h = 1; h <= 3; h++) s += Math.sin((2 * Math.PI * h * f * i) / SR) / h;
      seg[i] = s * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (v - 1))); // 한(Hann) 창
      peak = Math.max(peak, Math.abs(seg[i]));
    }
    for (let i = 0; i < v; i++) y[k * L + i] = (amp * seg[i]) / peak;
  }
  for (let i = 0; i < y.length; i++) y[i] += 0.0005 * gauss(rnd);
  return y;
}

function f0Of(y: Float32Array, start: number, len: number, fmin: number = 70, fmax: number = 400): number {
  // 자기상관으로 한 조각의 높낮이(Hz): 같은 모양이 되풀이되는 간격(lag)을 찾는다
  let mean = 0;
  for (let i = 0; i < len; i++) mean += y[start + i];
  mean /= len;
  const lo = Math.floor(SR / fmax);
  const hi = Math.floor(SR / fmin);
  let best = lo;
  let bestV = -Infinity;
  for (let lag = lo; lag < hi; lag++) {
    let s = 0;
    for (let i = 0; i < len - lag; i++) s += (y[start + i] - mean) * (y[start + i + lag] - mean);
    if (s > bestV) {
      bestV = s;
      best = lag;
    }
  }
  return SR / best;
}

function median(a: number[]): number {
  const s = [...a].sort((p, q) => p - q);
  const m = s.length >> 1;
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
}

interface Prosody {
  f0: number;
  db: number;
  pause: number;
  rate: number;
}

function prosody(y: Float32Array): Prosody {
  // 말투 숫자 네 개: 높낮이(f0) · 크기(db) · 쉼 비율(pause) · 말속도(rate, 음절/초)
  const nfr = Math.floor((y.length - 640) / HOP) + 1;
  const db: number[] = [];
  for (let f = 0; f < nfr; f++) {
    let s = 0;
    for (let i = 0; i < 640; i++) s += y[f * HOP + i] ** 2;
    db.push(20 * Math.log10(Math.sqrt(s / 640) + 1e-9));
  }
  let mx = -Infinity;
  for (const d of db) mx = Math.max(mx, d);
  const speech = db.map((d) => d > mx - 30); // 가장 큰 곳보다 30 dB 넘게 작으면 '쉼'
  const core = speech.slice(speech.indexOf(true), speech.lastIndexOf(true) + 1); // 첫 말 ~ 마지막 말 사이
  let onsets = 0;
  for (let i = 0; i < speech.length; i++) if (speech[i] && (i === 0 || !speech[i - 1])) onsets++; // 쉼 → 말 = 음절 수
  const talk = db.filter((_, i) => speech[i]);
  const loud: number[] = [];
  db.forEach((d, i) => {
    if (d > mx - 6) loud.push(i);
  });
  const m = Math.min(12, loud.length);
  const pick: number[] = [];
  for (let j = 0; j < m; j++) pick.push(loud[Math.floor((j * (loud.length - 1)) / Math.max(1, m - 1))]);
  return {
    f0: median(pick.map((i) => f0Of(y, i * HOP, 640))),
    db: talk.reduce((p, q) => p + q, 0) / talk.length,
    pause: 1 - core.filter(Boolean).length / core.length,
    rate: onsets / ((core.length * HOP) / SR),
  };
}


const EV_NAMES: Record<string, string> = { siren: "사이렌", knock: "문 두드림", glass: "유리 깨짐", cough: "기침", quiet: "조용한 방", speech: "말소리" };
const NOT_EVENT = ["quiet", "speech"]; // 찾는 소리가 아닌 것들: 조용한 방 · 사람 말소리
const WIN = 2.0; // 창 길이(초) = 훈련 조각 길이
const REJECT = 0.9; // 가장 가까운 종류와도 이만큼 멀면 '모름'으로 거절

function eventSound(kind: string, rnd: () => number, sec: number = WIN): Float32Array {
  // [대체] 실제 ESC-50 녹음 대신 만든 소리 이벤트. 조각 안에서 시작 위치만 조금씩 달라진다
  const n = Math.floor(sec * SR);
  const y = new Float32Array(n);
  for (let i = 0; i < n; i++) y[i] = 0.003 * gauss(rnd);
  const s0 = 0.3 + 0.3 * rnd();
  const put = (x: Float32Array, at: number): void => {
    const i0 = Math.floor(at * SR);
    for (let i = Math.max(0, -i0); i < x.length && i0 + i < n; i++) y[i0 + i] += x[i];
  };
  if (kind === "siren") {
    // 600~1200 Hz를 오르내리는 소리 1초
    const x = new Float32Array(SR);
    const ph = 6 * rnd();
    let phase = 0;
    for (let i = 0; i < SR; i++) {
      phase += (2 * Math.PI * (600 + 300 * (1 + Math.sin((2 * Math.PI * 0.8 * i) / SR + ph)))) / SR;
      x[i] = 0.5 * Math.sin(phase);
    }
    put(x, s0);
  } else if (kind === "knock") {
    // 150 Hz 둔탁한 소리가 빠르게 줄어듦 x 3
    const x = new Float32Array(Math.floor(0.1 * SR));
    for (let i = 0; i < x.length; i++) x[i] = 0.8 * Math.sin((2 * Math.PI * 150 * i) / SR) * Math.exp(-i / SR / 0.03);
    for (let k = 0; k < 3; k++) put(x, s0 + 0.25 * k);
  } else if (kind === "glass") {
    // 높은 소리 위주의 잡음이 확 터졌다 사라짐
    const m = Math.floor(0.4 * SR);
    const x = new Float32Array(m);
    let prev = gauss(rnd);
    for (let i = 0; i < m; i++) {
      const g = gauss(rnd);
      x[i] = 0.5 * (g - prev) * Math.exp(-i / SR / 0.08);
      prev = g;
    }
    put(x, s0);
  } else if (kind === "cough") {
    // 낮은 쪽 잡음이 짧게 세 번
    const m = Math.floor(0.15 * SR);
    for (let k = 0; k < 3; k++) {
      const g = Array.from({ length: m + 3 }, () => gauss(rnd));
      const x = new Float32Array(m);
      for (let i = 0; i < m; i++) x[i] = 0.8 * ((g[i] + g[i + 1] + g[i + 2] + g[i + 3]) / 4) * Math.exp(-i / SR / 0.05);
      put(x, s0 + 0.3 * k);
    }
  }
  if (kind === "speech") {
    // 사람 말소리(합성): 높낮이 · 말속도 · 세기를 조금씩 바꿔서
    const r = 4 + 2 * rnd();
    return speak(120 + 70 * rnd(), r, 0.3 + 0.4 * rnd(), Math.floor(sec * r) + 1, Math.floor(rnd() * 1e6)).slice(0, n);
  }
  return y;
}

function evFeat(y: Float32Array): number[] {
  // 소리 특징 세 개: 소리 나는 곳의 영점 통과율 · 뾰족함(crest) · 소리가 이어진 길이(로그). 창이 소리를 일부만 잘라도 크게 안 변한다
  const nf = Math.floor(y.length / 320);
  const r: number[] = [];
  let rmax = 0;
  for (let f = 0; f < nf; f++) {
    let s = 0;
    for (let i = 0; i < 320; i++) s += y[f * 320 + i] ** 2;
    r.push(Math.sqrt(s / 320));
    rmax = Math.max(rmax, r[f]);
  }
  let zsum = 0;
  let act = 0;
  let sq = 0;
  const runs: number[] = [];
  let k = 0;
  for (let f = 0; f < nf; f++) {
    if (r[f] <= 0.1 * rmax) {
      if (k) runs.push(k); // 소리 나는 조각이 몇 개씩 이어지나
      k = 0;
      continue;
    }
    k++;
    act++;
    let z = 0;
    for (let i = 0; i < 320; i++) sq += y[f * 320 + i] ** 2;
    for (let i = 1; i < 320; i++) if (y[f * 320 + i] < 0 !== y[f * 320 + i - 1] < 0) z++;
    zsum += z / 319;
  }
  if (k) runs.push(k);
  let peak = 0;
  for (const v of y) peak = Math.max(peak, Math.abs(v));
  return [zsum / act, peak / Math.sqrt(sq / (act * 320)), Math.log(median(runs))];
}

interface EvModel {
  mu: number[];
  sd: number[];
  cent: Record<string, number[]>;
}

function trainEvents(seed: number = 0, per: number = 12): EvModel {
  const rnd = mulberry32(seed);
  const X: Record<string, number[][]> = {};
  for (const k of Object.keys(EV_NAMES)) X[k] = Array.from({ length: per }, () => evFeat(eventSound(k, rnd)));
  const all = Object.values(X).flat();
  const mu = [0, 1, 2].map((j) => all.reduce((s, v) => s + v[j], 0) / all.length);
  const sd = [0, 1, 2].map((j) => Math.sqrt(all.reduce((s, v) => s + (v[j] - mu[j]) ** 2, 0) / all.length) + 1e-6);
  const cent: Record<string, number[]> = {};
  for (const [k, rows] of Object.entries(X)) cent[k] = [0, 1, 2].map((j) => rows.reduce((s, v) => s + (v[j] - mu[j]) / sd[j], 0) / rows.length);
  return { mu, sd, cent }; // 종류마다 대표 점(중심)
}

function classify(y: Float32Array, m: EvModel): { label: string; d: Record<string, number> } {
  // 가장 가까운 종류와 거리. 거리가 REJECT보다 멀면 '모름'
  const z = evFeat(y).map((v, j) => (v - m.mu[j]) / m.sd[j]);
  const d: Record<string, number> = {};
  for (const [k, c] of Object.entries(m.cent)) d[k] = Math.hypot(z[0] - c[0], z[1] - c[1], z[2] - c[2]);
  const best = Object.keys(d).reduce((p, q) => (d[q] < d[p] ? q : p));
  return { label: d[best] < REJECT ? best : "모름", d };
}

function segments(times: number[], flags: boolean[], win: number): Array<[number, number]> {
  // 켜진 창이 이어지면 하나의 (시작, 끝) 구간으로
  const segs: Array<[number, number]> = [];
  let start: number | null = null;
  let prev = 0;
  times.forEach((t, i) => {
    if (flags[i] && start === null) start = t; // 꺼짐 → 켜짐: 구간 시작
    if (!flags[i] && start !== null) {
      segs.push([start, prev + win]); // 켜짐 → 꺼짐: 구간 끝
      start = null;
    }
    prev = t;
  });
  if (start !== null) segs.push([start, prev + win]);
  return segs;
}

function overlap(a: [number, number], b: [number, number]): number {
  // 두 구간(시작, 끝)이 겹치는 길이(초). 겹치지 않으면 0
  return Math.max(0, Math.min(a[1], b[1]) - Math.max(a[0], b[0]));
}

function detect(y: Float32Array, m: EvModel, win: number = WIN, hop: number = 1.0): Array<[number, number, string]> {
  // 긴 녹음 → [(시작, 끝, 종류), ...]. 창을 hop씩 옮기며 분류한다
  const n = Math.floor(win * SR);
  const h = Math.floor(hop * SR);
  const times: number[] = [];
  const labels: string[] = [];
  for (let i = 0; i < Math.max(1, y.length - n + 1); i += h) {
    times.push(i / SR);
    labels.push(classify(y.subarray(i, i + n), m).label);
  }
  const found: Array<[number, number, string]> = [];
  for (const c of Object.keys(EV_NAMES)) {
    if (NOT_EVENT.includes(c)) continue;
    for (const [s, e] of segments(times, labels.map((l) => l === c), win)) found.push([s, e, c]);
  }
  return found.sort((p, q) => p[0] - q[0]);
}


const W_RATE = 2.0;
const W_PITCH = 0.25;
const W_LOUD = 0.08; // 말속도 50% 빨라짐 = 1.0 · 높낮이 4반음 = 1.0 · 크기 12.5 dB = 1.0
const AROUSAL_TH = 1.0; // 이 이상이면 '들뜸' 신호

function semitones(f: number, ref: number): number {
  // ref에서 f까지 몇 반음 올라갔나(내려가면 음수): 한 옥타브(2배) = 12반음
  return 12 * Math.log2(f / ref);
}

function arousal(f: Prosody, base: Prosody): number {
  // 기준선과 비교한 '들뜸 점수': 말속도 비율 + 높낮이 반음 + 크기 dB 차이를 가중합
  return W_RATE * (f.rate / base.rate - 1) + W_PITCH * semitones(f.f0, base.f0) + W_LOUD * (f.db - base.db);
}


// ── Part 1 · 준언어 특징: '어떻게' 말했나 ──
{
  const STYLES: Record<string, [number, number, number]> = {
    차분: [140, 4.0, 0.3],
    서두름: [168, 6.0, 0.35],
    "큰 소리": [190, 4.4, 0.8],
    가라앉음: [118, 3.0, 0.15],
  }; // [높낮이 Hz, 말속도 음절/초, 세기]
  const FEAT: Record<string, Prosody> = {};
  for (const [k, v] of Object.entries(STYLES)) {
    FEAT[k] = prosody(speak(v[0], v[1], v[2]));
    const f = FEAT[k];
    console.log(`${k}: 높낮이 ${f.f0.toFixed(0)} Hz · 크기 ${f.db.toFixed(1)} dB · 쉼 비율 ${(f.pause * 100).toFixed(0)}% · 말속도 ${f.rate.toFixed(1)}음절/초`);
  }
  const calm = FEAT["차분"];
  const hurry = FEAT["서두름"];
  const loud = FEAT["큰 소리"];
  const low = FEAT["가라앉음"];
  check(
    hurry.rate > 1.3 * calm.rate && loud.db > calm.db + 6 && low.f0 < calm.f0 && calm.f0 < hurry.f0 && hurry.f0 < loud.f0 && low.rate < calm.rate && calm.pause > 0.1 && calm.pause < 0.6,
    "서두른 말은 말속도가 빠르고, 큰 소리는 6 dB 넘게 크고, 높낮이는 가라앉음 < 차분 < 서두름 < 큰 소리 순서여야 해요.",
  );
}


// ── Part 1-1 · 기준선과 들뜸 점수 ──
{
  const semis = [semitones(440, 220), semitones(110, 220), semitones(150, 120)].map((v) => Math.round(v * 10000) / 10000);
  check(semis.join() === [12, -12, 3.8631].join(), "반음 = 12 * log2(f / ref)");
  const BASE = prosody(speak(120, 4.0, 0.3)); // 이 사람의 평소 말투(낮은 목소리)
  const CALM_HI = prosody(speak(210, 4.0, 0.3, 10, 1)); // 목소리가 원래 높은 사람의 차분한 말
  const LOUD_LO = prosody(speak(170, 5.0, 0.7, 10, 2)); // 낮은 목소리 사람이 큰 소리로 말함
  console.log(`절대 높낮이: 높은 목소리의 차분한 말 ${CALM_HI.f0.toFixed(0)} Hz vs 낮은 목소리의 큰 소리 ${LOUD_LO.f0.toFixed(0)} Hz`);
  console.log(`들뜸 점수: 높은 목소리 ${arousal(CALM_HI, CALM_HI).toFixed(2)} · 낮은 목소리의 큰 소리 ${arousal(LOUD_LO, BASE).toFixed(2)}`);
  check(
    Math.abs(arousal(BASE, BASE)) < 1e-9 && CALM_HI.f0 > LOUD_LO.f0 && arousal(LOUD_LO, BASE) >= AROUSAL_TH && AROUSAL_TH > arousal(CALM_HI, CALM_HI),
    "절대 문턱이면 높은 목소리가 늘 흥분으로 보여요. 기준선과 비교하면 기준선 자신은 0점, 큰 소리만 문턱을 넘어요.",
  );
}


// ── Part 2 · 감정 인식 모델: 맞히는 것과 틀리는 것 ──
{
  // [대체] emotion2vec+ 대신: 말투 숫자(높낮이 · 크기 · 말속도)의 '가장 가까운 중심' 분류기. 감정마다 말투 범위가 겹치게 만들어 혼동이 생긴다.
  const RANGE: Record<string, number[]> = {
    neutral: [130, 150, 3.8, 4.4, 0.25, 0.35],
    sad: [110, 125, 2.8, 3.4, 0.1, 0.2],
    angry: [160, 190, 5.0, 6.0, 0.6, 0.9],
    happy: [160, 200, 4.8, 5.8, 0.4, 0.6],
  }; // [f0 범위, 말속도 범위, 세기 범위]
  const EMO_KO: Record<string, string> = { neutral: "중립", sad: "슬픔", angry: "화남", happy: "기쁨" };
  const rng = mulberry32(7);
  const uni = (lo: number, hi: number): number => lo + (hi - lo) * rng();

  function acted(emo: string): number[] {
    const a = RANGE[emo];
    const p = prosody(speak(uni(a[0], a[1]), uni(a[2], a[3]), uni(a[4], a[5]), 8, Math.floor(rng() * 1e6)));
    return [p.f0, p.db, p.rate];
  }

  const EMOS = Object.keys(RANGE);
  const TRAIN: Record<string, number[][]> = {};
  for (const e of EMOS) TRAIN[e] = Array.from({ length: 6 }, () => acted(e));
  const TEST: Array<[string, number[]]> = [];
  for (const e of EMOS) for (let i = 0; i < 6; i++) TEST.push([e, acted(e)]);
  const allx = Object.values(TRAIN).flat();
  const mu = [0, 1, 2].map((j) => allx.reduce((s, v) => s + v[j], 0) / allx.length);
  const sd = [0, 1, 2].map((j) => Math.sqrt(allx.reduce((s, v) => s + (v[j] - mu[j]) ** 2, 0) / allx.length));
  const CENT: Record<string, number[]> = {};
  for (const [e, rows] of Object.entries(TRAIN)) CENT[e] = [0, 1, 2].map((j) => rows.reduce((s, v) => s + (v[j] - mu[j]) / sd[j], 0) / rows.length);

  function emotion(x: number[]): Array<[string, number]> {
    // 말투 숫자 → [감정, 확률]: 중심까지 거리가 가까울수록 확률이 크다(softmax). 큰 순서로 정렬
    const w = EMOS.map((e) => Math.exp(-[0, 1, 2].reduce((s, j) => s + ((x[j] - mu[j]) / sd[j] - CENT[e][j]) ** 2, 0) / 2));
    const tot = w.reduce((p, q) => p + q, 0);
    return EMOS.map((e, i): [string, number] => [e, w[i] / tot]).sort((p, q) => q[1] - p[1]);
  }

  function decide(probs: Array<[string, number]>, minConf: number = 0.6): string {
    // 확률이 가장 큰 감정을 답하되, 그 확률이 minConf보다 작으면 '불확실'
    const best = probs.reduce((p, q) => (q[1] > p[1] ? q : p));
    return best[1] >= minConf ? best[0] : "불확실";
  }

  const PROBS = TEST.map(([e, x]): [string, Array<[string, number]>] => [e, emotion(x)]);
  const hit = PROBS.filter(([e, p]) => p[0][0] === e).length / PROBS.length;
  const wrong = [...new Set(PROBS.filter(([e, p]) => p[0][0] !== e).map(([e, p]) => `${EMO_KO[e]}→${EMO_KO[p[0][0]]}`))];
  console.log(`맞힌 비율 ${(hit * 100).toFixed(0)}% (${PROBS.length}개) · 헷갈린 쌍(실제 → 답): ${wrong.join(", ") || "없음"}`);
  const rows: Array<[number, number]> = [];
  for (const th of [0, 0.5, 0.7, 0.9]) {
    const said = PROBS.filter(([, p]) => decide(p, th) !== "불확실");
    const acc = said.length ? said.filter(([e, p]) => decide(p, th) === e).length / said.length : NaN;
    rows.push([th, said.length / PROBS.length]);
    console.log(`확신 문턱 ${th}: 답한 비율 ${((said.length / PROBS.length) * 100).toFixed(0)}% · 답한 것 중 맞힌 비율 ${(acc * 100).toFixed(0)}%`);
  }
  const okVec =
    decide([["angry", 0.7], ["sad", 0.2], ["neutral", 0.1]]) === "angry" &&
    decide([["angry", 0.45], ["sad", 0.4], ["neutral", 0.15]]) === "불확실" &&
    decide([["neutral", 0.6], ["sad", 0.4]], 0.6) === "neutral";
  check(
    Math.abs(PROBS[0][1].reduce((s, kv) => s + kv[1], 0) - 1) < 1e-6 && hit > 0.6 && rows[0][1] === 1 && rows.every((r, i) => i === 0 || rows[i - 1][1] >= r[1]) && okVec,
    "확률은 더해서 1, 문턱을 올리면 답하는 비율은 줄어야 해요.",
  );
}


// ── Part 2-2 · 감정 타임라인(창 + 이동 평균) ──
{
  function windows(y: Float32Array, win: number = 2.5, hop: number = 0.5, sr: number = SR): Array<[number, Float32Array]> {
    // [(시작 시각, 조각), ...]: 창을 hop씩 옮긴다
    const n = Math.floor(win * sr);
    const h = Math.floor(hop * sr);
    const out: Array<[number, Float32Array]> = [];
    for (let i = 0; i < Math.max(1, y.length - n + 1); i += h) out.push([i / sr, y.subarray(i, i + n)]);
    return out;
  }

  function smooth(p: number[], k: number = 3): number[] {
    // 앞뒤 창의 이동 평균(k는 홀수): 튀는 값을 다듬는다. 가장자리는 0으로 간주
    const half = Math.floor(k / 2);
    return p.map((_, i) => {
      let s = 0;
      for (let j = i - half; j <= i + half; j++) if (j >= 0 && j < p.length) s += p[j];
      return s / k;
    });
  }

  // 평소 말투 6초 → 서두르고 큰 목소리 6초 → 다시 평소 말투 4초 (바뀌는 시각 = 6초)
  const STYLE: number[][] = [
    [120, 4.0, 0.3, 24],
    [170, 6.0, 0.7, 36],
    [120, 4.0, 0.3, 16],
  ];
  const parts = STYLE.map(([f, r, a, n], i) => speak(f, r, a, n, i));
  const LONG = new Float32Array(parts.reduce((s, p) => s + p.length, 0));
  let off = 0;
  for (const p of parts) {
    LONG.set(p, off);
    off += p.length;
  }
  const CHANGE = 6.0;
  const W = windows(LONG);
  const FEATS = W.map(([, w]) => prosody(w));
  const raw = FEATS.map((f) => arousal(f, FEATS[0])); // 첫 창 = 이 사람의 기준선
  const sm = smooth(raw, 3);
  const centers = W.map(([s]) => s + 1.25); // 창의 가운데 시각
  const first = sm.findIndex((v) => v >= AROUSAL_TH);
  console.log(`창 ${W.length}개 · 들뜸 점수(다듬은 것): ${sm.map((v) => v.toFixed(1)).join(" ")}`);
  console.log(`처음 문턱을 넘은 창의 가운데 시각 ${centers[first].toFixed(2)}초 (실제로 바뀐 시각 ${CHANGE}초)`);
  check(
    W.length === Math.floor((LONG.length / SR - 2.5) / 0.5) + 1 &&
      smooth([0, 0, 3, 0, 0]).join() === [0, 1, 1, 1, 0].join() &&
      first > 0 &&
      sm[first - 1] < AROUSAL_TH &&
      Math.abs(centers[first] - CHANGE) <= 2.0,
    "창 개수 = (길이 - 창) / 간격 + 1, 이동 평균으로 바뀐 시각 근처에서 문턱을 넘어야 해요.",
  );
}


// ── Part 3 · 소리 이벤트: 말이 아닌 소리 듣기 ──
{
  const model = trainEvents(0);
  const rnd = mulberry32(1);
  const tests: Array<[string, Float32Array]> = [];
  for (const k of Object.keys(EV_NAMES)) for (let i = 0; i < 5; i++) tests.push([k, eventSound(k, rnd)]);
  const pred = tests.map(([k, y]) => ({ k, ...classify(y, model) }));
  const acc = pred.filter((p) => p.label === p.k).length / pred.length;
  console.log(`닫힌 목록 분류기: 소리 ${tests.length}개 중 ${(acc * 100).toFixed(0)}% 맞힘 (종류 ${Object.keys(EV_NAMES).length}가지: ${Object.values(EV_NAMES).join(", ")})`);
  const w = Object.entries(pred[0].d).map(([k, d]): [string, number] => [k, Math.exp(-(d ** 2) / 2)]);
  const tot = w.reduce((s, kv) => s + kv[1], 0);
  const probs = w.map(([k, v]): [string, number] => [k, v / tot]).sort((p, q) => q[1] - p[1]);
  console.log("첫 소리의 상위 3개:", probs.slice(0, 3).map(([k, v]) => `${EV_NAMES[k]} ${v.toFixed(3)}`).join(", "));
  // 목록에 없는 소리(낮게 계속 웅웅대는 환풍기 소리): 닫힌 목록은 어떻게든 하나를 고르지만, 거리가 멀면 '모름'
  const noise = Array.from({ length: 2 * SR + 31 }, () => gauss(rnd));
  const hum = new Float32Array(2 * SR);
  for (let i = 0; i < hum.length; i++) {
    let s = 0;
    for (let j = 0; j < 32; j++) s += noise[i + j];
    hum[i] = (3 * s) / 32; // 32개씩 평균 = 낮은 소리만 남은 잡음
  }
  const h = classify(hum, model);
  const near = Object.keys(h.d).reduce((p, q) => (h.d[q] < h.d[p] ? q : p));
  const knownFar = Math.max(...pred.map((p) => Math.min(...Object.values(p.d))));
  console.log(`목록에 없는 환풍기 소리: 억지로 고르면 '${EV_NAMES[near]}'(거리 ${h.d[near].toFixed(2)}) → 거절 규칙 적용 결과 '${h.label}' · 아는 소리의 가장 먼 거리 ${knownFar.toFixed(2)}`);
  check(acc >= 0.9 && Math.abs(probs.reduce((s, kv) => s + kv[1], 0) - 1) < 1e-9 && h.label === "모름" && knownFar < REJECT, "아는 소리는 90% 넘게 맞히고, 목록에 없는 소리는 '모름'으로 거절해야 해요.");
}


// ── Part 3 · 긴 녹음에서 이벤트 구간 찾기 ──
{
  const model = trainEvents(0);
  const rnd = mulberry32(3);
  const PLAN: Record<number, string> = { 1: "cough", 5: "knock", 9: "glass", 13: "siren" }; // 2초 조각 16개 중 이벤트가 들어간 조각 번호
  const pieces = Array.from({ length: 16 }, (_, i) => eventSound(PLAN[i] ?? "quiet", rnd));
  const STREAM = new Float32Array(pieces.reduce((s, p) => s + p.length, 0)); // 32초 녹음
  pieces.forEach((p, i) => STREAM.set(p, i * p.length));
  const TRUTH: Array<[number, number, string]> = Object.entries(PLAN).map(([i, c]): [number, number, string] => [2 * Number(i), 2 * Number(i) + 2, c]);
  const FOUND = detect(STREAM, model);
  let missed = 0;
  for (const [s, e, c] of TRUTH) {
    const got = FOUND.filter((f) => f[2] === c && overlap([s, e], [f[0], f[1]]) > 0);
    if (!got.length) missed++;
    console.log(`실제 ${EV_NAMES[c]} ${s}~${e}초 → 찾은 구간 ${got.map((g) => `${g[0]}~${g[1]}`).join(", ") || "놓침"}`);
  }
  const falseAlarm = FOUND.filter((f) => !TRUTH.some(([s, e, c]) => c === f[2] && overlap([s, e], [f[0], f[1]]) > 0));
  console.log(`놓친 소리 ${missed}개 · 오경보 ${falseAlarm.length}개: ${falseAlarm.map((f) => `${EV_NAMES[f[2]]} ${f[0]}~${f[1]}`).join(", ")}`);
  check(overlap([0, 5], [3, 8]) === 2 && overlap([0, 2], [5, 7]) === 0 && overlap([0, 3], [3, 6]) === 0 && missed === 0 && falseAlarm.length <= 1, "겹침 = min(끝) - max(시작) (음수면 0). 이벤트는 모두 찾고 오경보는 1개 이하여야 해요.");
}


// ── Part 4 · 신호를 모아 에스컬레이션 규칙 ──
{
  const COMPLAINT = ["책임자", "환불", "왜 이렇게", "세 번째"]; // 항의 표현 낱말
  const DANGER = ["glass", "siren"]; // 들리면 바로 확인해야 하는 소리

  interface Signal {
    arousal: number;
    complaint: boolean;
    danger: boolean;
  }

  function escalate(history: Signal[]): string {
    // ① 한 번이라도 danger → 긴급 확인 ② 마지막 두 발화가 모두 들뜸 → 상담원 연결 ③ 마지막 발화에 항의 → 상담원 연결 ④ 계속
    if (history.some((h) => h.danger)) return "긴급 확인";
    if (history.length >= 2 && history.slice(-2).every((h) => h.arousal >= AROUSAL_TH)) return "상담원 연결";
    if (history.length && history[history.length - 1].complaint) return "상담원 연결";
    return "계속";
  }

  const H = (a: number, c: boolean = false, d: boolean = false): Signal => ({ arousal: a, complaint: c, danger: d });
  const ruleOk =
    [
      escalate([]),
      escalate([H(1.4)]),
      escalate([H(1.2), H(1.3)]),
      escalate([H(1.2), H(0.2)]),
      escalate([H(0.0), H(0.1, true)]),
      escalate([H(0.1, true), H(0.0)]),
      escalate([H(0.2, false, true), H(0.0)]),
      escalate([H(1.5), H(1.5, false, true)]),
    ].join() === ["계속", "계속", "상담원 연결", "계속", "상담원 연결", "계속", "긴급 확인", "긴급 확인"].join();
  check(ruleOk, "위험 소리가 가장 먼저, 그다음 두 번 연속 들뜸, 그다음 마지막 발화의 항의 표현 순서로 검사해요.");

  // 가상 통화: 손님 채널에 발화 4개 + 마지막에 유리 깨지는 소리. [대체] 받아쓰기(Whisper) 대신 대본 글자를 그대로 쓴다
  const model = trainEvents(0);
  const CALL: Array<[string, string, number[]]> = [
    ["차분", "안녕하세요 예약 확인하려고요", [120, 4.0, 0.3]],
    ["차분", "어제 상담받았는데요", [120, 4.0, 0.3]],
    ["서두름", "그런데 왜 이렇게 오래 걸려요", [165, 6.0, 0.4]],
    ["큰 소리", "책임자 바꿔 주세요", [175, 5.0, 0.8]],
  ];
  const rnd = mulberry32(5);
  const chan: Float32Array[] = [];
  const turns: Array<{ style: string; text: string; start: number; wav: Float32Array }> = [];
  let t = 0;
  CALL.forEach(([style, text, [f0, rate, amp]], i) => {
    const y = speak(f0, rate, amp, 10, 10 + i);
    const gap = eventSound("quiet", rnd, 1.0);
    turns.push({ style, text, start: t, wav: y });
    chan.push(y, gap);
    t += (y.length + gap.length) / SR;
  });
  chan.push(eventSound("glass", rnd)); // 마지막 발화 뒤에 유리 깨지는 소리
  const CHANNEL = new Float32Array(chan.reduce((s, p) => s + p.length, 0));
  let pos = 0;
  for (const p of chan) {
    CHANNEL.set(p, pos);
    pos += p.length;
  }
  const FOUND = detect(CHANNEL, model);
  const HIST: Signal[] = [];
  let base: Prosody | null = null;
  turns.forEach((u, k) => {
    const f = prosody(u.wav);
    base = base ?? f; // 첫 발화 = 이 손님의 기준선
    const nxt = k + 1 < turns.length ? turns[k + 1].start : CHANNEL.length / SR;
    const near = FOUND.filter(([s, e]) => s < nxt && e > u.start).map((x) => x[2]); // 이 발화부터 다음 발화 전까지 들린 소리
    HIST.push({ arousal: Math.round(arousal(f, base) * 100) / 100, complaint: COMPLAINT.some((w) => u.text.includes(w)), danger: near.some((c) => DANGER.includes(c)) });
  });
  const ACTIONS = HIST.map((_, i) => escalate(HIST.slice(0, i + 1)));
  turns.forEach((u, i) => console.log(`${u.start.toFixed(1)}초 ${u.style} 들뜸 ${HIST[i].arousal.toFixed(2)} 항의 ${HIST[i].complaint ? "O" : "-"} 위험 ${HIST[i].danger ? "O" : "-"} → ${ACTIONS[i]}`));
  check(HIST[0].arousal === 0 && ACTIONS.join() === ["계속", "계속", "상담원 연결", "긴급 확인"].join(), "첫 발화는 기준선(0점), 항의가 나오면 상담원 연결, 유리 깨짐은 긴급 확인이어야 해요.");
}

prosody.typescript:
// D36 · Part 1 · 준언어 특징: '어떻게' 말했나 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d36_prosody.ts   (소리·데이터는 코드 안에서 합성해요)
//   높낮이 · 크기 · 쉼 · 말속도를 숫자 네 개로 재기


const SR = 16000; // 말소리 분석용 표본화율 (16 kHz)
const HOP = 320; // 20 ms마다 한 번 잼

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}

function speak(f0: number = 140, rate: number = 4, amp: number = 0.3, nSyl: number = 10, seed: number = 0): Float32Array {
  // [대체] TTS 대신 배음 3개짜리 합성 말소리: 음절마다 앞 70%는 소리, 뒤 30%는 쉼
  const rnd = mulberry32(seed);
  const L = Math.floor(SR / rate);
  const v = Math.floor(L * 0.7);
  const y = new Float32Array(nSyl * L);
  for (let k = 0; k < nSyl; k++) {
    const f = f0 * (1 + 0.03 * Math.sin(1.7 * k)); // 억양이 조금 흔들림
    const seg = new Float64Array(v);
    let peak = 0;
    for (let i = 0; i < v; i++) {
      let s = 0;
      for (let h = 1; h <= 3; h++) s += Math.sin((2 * Math.PI * h * f * i) / SR) / h;
      seg[i] = s * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (v - 1))); // 한(Hann) 창
      peak = Math.max(peak, Math.abs(seg[i]));
    }
    for (let i = 0; i < v; i++) y[k * L + i] = (amp * seg[i]) / peak;
  }
  for (let i = 0; i < y.length; i++) y[i] += 0.0005 * gauss(rnd);
  return y;
}

function f0Of(y: Float32Array, start: number, len: number, fmin: number = 70, fmax: number = 400): number {
  // 자기상관으로 한 조각의 높낮이(Hz): 같은 모양이 되풀이되는 간격(lag)을 찾는다
  let mean = 0;
  for (let i = 0; i < len; i++) mean += y[start + i];
  mean /= len;
  const lo = Math.floor(SR / fmax);
  const hi = Math.floor(SR / fmin);
  let best = lo;
  let bestV = -Infinity;
  for (let lag = lo; lag < hi; lag++) {
    let s = 0;
    for (let i = 0; i < len - lag; i++) s += (y[start + i] - mean) * (y[start + i + lag] - mean);
    if (s > bestV) {
      bestV = s;
      best = lag;
    }
  }
  return SR / best;
}

function median(a: number[]): number {
  const s = [...a].sort((p, q) => p - q);
  const m = s.length >> 1;
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
}

interface Prosody {
  f0: number;
  db: number;
  pause: number;
  rate: number;
}

function prosody(y: Float32Array): Prosody {
  // 말투 숫자 네 개: 높낮이(f0) · 크기(db) · 쉼 비율(pause) · 말속도(rate, 음절/초)
  const nfr = Math.floor((y.length - 640) / HOP) + 1;
  const db: number[] = [];
  for (let f = 0; f < nfr; f++) {
    let s = 0;
    for (let i = 0; i < 640; i++) s += y[f * HOP + i] ** 2;
    db.push(20 * Math.log10(Math.sqrt(s / 640) + 1e-9));
  }
  let mx = -Infinity;
  for (const d of db) mx = Math.max(mx, d);
  const speech = db.map((d) => d > mx - 30); // 가장 큰 곳보다 30 dB 넘게 작으면 '쉼'
  const core = speech.slice(speech.indexOf(true), speech.lastIndexOf(true) + 1); // 첫 말 ~ 마지막 말 사이
  let onsets = 0;
  for (let i = 0; i < speech.length; i++) if (speech[i] && (i === 0 || !speech[i - 1])) onsets++; // 쉼 → 말 = 음절 수
  const talk = db.filter((_, i) => speech[i]);
  const loud: number[] = [];
  db.forEach((d, i) => {
    if (d > mx - 6) loud.push(i);
  });
  const m = Math.min(12, loud.length);
  const pick: number[] = [];
  for (let j = 0; j < m; j++) pick.push(loud[Math.floor((j * (loud.length - 1)) / Math.max(1, m - 1))]);
  return {
    f0: median(pick.map((i) => f0Of(y, i * HOP, 640))),
    db: talk.reduce((p, q) => p + q, 0) / talk.length,
    pause: 1 - core.filter(Boolean).length / core.length,
    rate: onsets / ((core.length * HOP) / SR),
  };
}


const STYLES: Record<string, [number, number, number]> = {
  차분: [140, 4.0, 0.3],
  서두름: [168, 6.0, 0.35],
  "큰 소리": [190, 4.4, 0.8],
  가라앉음: [118, 3.0, 0.15],
}; // [높낮이 Hz, 말속도 음절/초, 세기]
const FEAT: Record<string, Prosody> = {};
for (const [k, v] of Object.entries(STYLES)) {
  FEAT[k] = prosody(speak(v[0], v[1], v[2]));
